Use urllib with proper exception handling for network issues and missing endpoints:

```python
from urllib.request import urlopen, Request, urlretrieve
import json
import sys

def fetch_with_headers(url, params=None):
    headers = {"Accept": "application/json"}
    if params:
        query_string = urlencode(params)
        url = f"{url}?{query_string}"

    req = Request(url, headers=headers)
    try:
        with urlopen(req, timeout=15) as response:
            # Read and decode response
            content = response.read().decode("utf-8")
            return json.loads(content)
    except urlopen.error as e:
        print(f"HTTP Error: {e.code} - {e.reason}", file=sys.stderr)
        raise
    except TimeoutError:
        print("Request timed out after 15 seconds", file=sys.stderr)
        raise
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        raise

# Usage
result = fetch_with_headers(
    "https://httpbin.org/get",
    params={"page": 1, "limit": 10}
)
print(json.dumps(result, indent=2))
```
The function constructs URLs safely, handles timeouts and HTTP errors gracefully, and returns structured JSON when successful.

